solution:
class Parrot:
    def __init__(self, name):
        self.name = name
        self.words = []

    def teach(self, word):
        self.words.append(word)

    def speak(self):
        return ", ".join(self.words)

alt:
class Parrot:
    def __init__(self, name, words=None):
        self.name = name
        self.words = words or []

    def teach(self, word):
        self.words = self.words + [word]

    def speak(self):
        return ", ".join(self.words)
